// 語の成り立ちを、学習者が読んで分かる説明に書き直した本文（2026-09-13 の手動確認）。
//
// もとの語源メモ（単語データの etymology.note）は、語根カードや関連語の自動リンクの材料として
// そのまま残し、学習者に見せる本文だけをここで差し替える。書き直しの決まり:
//  - 言語名は「ラテン語」「古ノルド語」のように省略しない
//  - 元の語の意味だけで終わらせず、今の意味へどうつながったかを書く（→「今の意味」）
//  - 部品に分けられる語は分けて意味を添える（ab-「離れて」＋ errāre「さまよう」）
//  - 同じ語源の語は、確かなものだけを添える
// 本文は素材JSONの SHA-256（先頭16桁）で固定し、1文字でも変えると品質GATEが落ちる。
const clear = (text, fingerprint) => Object.freeze({
  note: text,
  reviewedAt: '2026-09-13',
  reviewedBy: 'manual-etymology-audit',
  fingerprint,
})

