  'athlete': clear('ギリシャ語 athlētēs「競技者」（athlon「競技の賞品」から）から。賞をかけて競う人→「運動選手」。', 'df11a3d9f4dd082c'),
  'atom': clear('ギリシャ語 atomos「分割できない」（a-「〜でない」＋ temnein「切る」）から。それ以上分けられない最小の粒と考えられた→「原子」。', '867d49589bfad4bf'),
  'atrocity': clear('ラテン語 atrōx「残忍な・恐ろしい」から。むごたらしい行い→「残虐行為」。', '56d28565f144cefc'),
  'attack': clear('イタリア語 attaccare「取りつく」から。「戦いを始める（戦いに取りつく）」という言い方から「攻撃する」の意味になった。attach（くっつける）と同じ語源。', '4384b313c58a0e8e'),
  'attorney': clear('古フランス語 atorné「任命された人」（atorner「割り当てる」から）から。本人の代わりを任された人→「代理人・弁護士」。', 'd9e9d01b704da55a'),
  'aunt': clear('ラテン語 amita「父方のおば」から、古フランス語 ante を経た語。英語では父方・母方を区別せず「おば」。', '69f6aff473e26f61'),
  'auspicious': clear('ラテン語 auspicium「鳥占い」（avis「鳥」＋ specere「見る」）から。鳥の飛び方でよい兆しを占った→「幸先のよい・縁起のよい」。', '4a81c713fcaa973e'),
  'automatic': clear('ギリシャ語 automatos「自分で動く」から。人の手を借りずに動く→「自動の」、考えずに体が動く→「無意識の」。', 'f62d08cf7f65e249'),
  'automation': clear('ギリシャ語 automatos「自分で動く」から来た automatic（自動の）をもとに、20世紀に作られた語。仕事を機械が自分でこなすようにすること→「自動化」。', '13ab77aab240310a'),
  'avarice': clear('ラテン語 avārus「貪欲な」から。お金や物を欲しがる心→「貪欲・強欲」。', '9ab1cf3ced3ff64c'),
  'avid': clear('ラテン語 avidus「強く欲しがる」から。何かを熱心に求める→「熱心な・貪欲な」。', '47db6a02a99b587c'),
  'avow': clear('ラテン語 advocāre「呼び寄せる」から、古フランス語 avouer「認める」を経た語。自分のことだと名乗り出る→「公言する・率直に認める」。advocate（主張する）と同じ語源。', 'cf3b0773b644e8a4'),
  'avuncular': clear('ラテン語 avunculus「（母方の）おじ」から。やさしく見守るおじのような→「おじのような・親しみやすい」。uncle（おじ）と同じ語源。', '2034c6754c75d1cc'),
  'award': clear('古北フランス語 eswarder「よく見て決める」から。審査して決めたうえで与える→「賞・授与する」。', '2e1276b80b2d178b'),
  'awe': clear('古ノルド語 agi「恐れ」から。おそれ多く思う気持ち→「畏敬・畏怖」。', '7f8941e66321d66e'),
