  'bad': clear('中英語 badde「悪い」から。それより前の由来ははっきりしない。', '85d5b2c361babfa8'),
  'baffle': clear('16世紀の baffle「辱める・笑いものにする」から（それより前の由来ははっきりしない）。人をまごつかせる→「当惑させる・困らせる」。', 'a408af4cc9c39105'),
  'bail': clear('古フランス語 baillier「預ける・引き渡す」から。お金を預けて身柄を引き取る→「保釈・保釈金」。', '5c2abeb0b5f19341'),
  'bait': clear('古ノルド語 beita「食いつかせる・えさを食べさせる」から。bite（かむ）と同じ語源。', 'f94271d93dbf833a'),
