  'ban': clear('古英語 bannan「命じる・呼び集める」から。公に命令を出す→「禁止する」。', '592c6c18ed3d79bf'),
  'banal': clear('フランス語 banal「（村人が）共同で使う」から。みんなが使うありふれたもの→「陳腐な・ありふれた」。', '6268cf604d59b622'),
  'bane': clear('古英語 bana「殺す者」から。命を奪うもの→「破滅のもと・悩みの種」。', 'e7d2be51663438cc'),
  'bankrupt': clear('イタリア語 banca rotta「壊れた台」から。お金を払えなくなった両替商の台を壊したことに由来するとされる→「破産した」。bank（銀行）と同じ語源。', 'ebd3b3238bfb5806'),
  'bare': clear('古英語 bær「裸の」から。何も覆っていない→「むき出しの・ありのままの」。', 'ed3077c367bb61da'),
