  'bark': clear('「ほえる」は古英語 beorcan「ほえる」から。「樹皮」の bark は古ノルド語 bǫrkr から来た別の語で、つづりがたまたま同じになった。', 'ab38dc5ac5ecc271'),
  'barrel': clear('古フランス語 baril「樽」から。樽のような筒→「銃身」。', 'b996df8ba71fc3ad'),
  'barren': clear('古フランス語 baraigne「子を産まない」から。作物が育たない土地→「不毛の・実りのない」。', 'f3698fc4ea7bff34'),
  'base': clear('ギリシャ語 basis「踏む所・台」から、ラテン語を経た語。足を置く台→「土台・基地」。basic（基本の）と同じ語源。', '2245bb63d80fe842'),
  'basin': clear('後期ラテン語 bacca「水入れ」から、古フランス語 bacin を経た語。水をためる器→「洗面器」、水が集まる低い土地→「盆地・流域」。', '376bf39406b5bc4f'),
  'bastion': clear('イタリア語 bastia「要塞」から（bastire「築く」にさかのぼる）。城壁から張り出したとりで→「牙城・最後の拠り所」。', '1e97de0752034cee'),
  'bawdy': clear('中英語 bawde「売春の仲立ちをする人」から。そうした人のような→「みだらな・きわどい」。', 'f26488c48cd36898'),
