  'beacon': clear('古英語 bēacen「合図・しるし」から。遠くに知らせる火→「のろし・標識灯」、進む道を示すもの→「指針」。', '47fc9d2e4e61ec1e'),
  'beak': clear('古フランス語 bec「くちばし」から（もとはガリアのケルト人のことば）。今と同じ「くちばし」を指す語。', 'b9319a00b934e9b6'),
  'beam': clear('古英語 bēam「木・柱」から。長い木材→「梁」、まっすぐ伸びる光→「光線」、顔を輝かせる→「ほほ笑む」。', 'b19d888349a84803'),
  'beard': clear('古英語 beard「ひげ」から。形も意味もほとんど変わっていない語。', '7d4b7b128d01bf2a'),
  'beg': clear('中英語 beggen「物乞いをする」から。それより前の由来ははっきりしない。', '8898b9d9a64feffb'),
  'beget': clear('古英語 begietan「手に入れる」（be-＋get）から。子を得る→「（子を）もうける」、そこから「生じさせる」。get と同じ語源。', '3df6533ddb7f07f1'),
  'behalf': clear('中英語 bi halve「〜の側に」から。half はもと「側」を表した。誰かの側に立って→「〜のために・代表して」。', 'd0dd20b692e83188'),
  'beleaguer': clear('オランダ語 belegeren「包囲する」から。leger は「陣営」で、周りに陣を張って囲む→「包囲する」、そこから「悩ます」。', '37d2f34eee1f05af'),
  'bell': clear('古英語 belle「鐘」から。昔から「鐘・鈴」を表してきた語。', '8a65203542b28464'),
