  'belt': clear('ラテン語 balteus「帯」から。腰に巻く帯→「ベルト」、帯のように細長く続く所→「地帯」。', '616f2ddba3edd4c8'),
  'bench': clear('古英語 benc「長いす」から。今と同じ「長いす・ベンチ」を指す語。', '2db18798f736f9fc'),
  'bend': clear('古英語 bendan「弓に弦を張る」から。弦を張ると弓が曲がることから→「曲げる・曲がる」。', 'ac8e845156dfbbb6'),
  'bequest': clear('古英語 becweþan「言い残す・遺言する」から来た bequeath（遺贈する）の名詞形。遺言で残すもの→「遺贈・遺産」。', '88a447e73aeef8bd'),
  'bevy': clear('中英語 bevey「（ヒバリやウズラなどの）群れ」から。それより前の由来は分かっていない。人の集まりにも使う→「一団」。', '1a7f896385337777'),
  'bilious': clear('ラテン語 bīlis「胆汁」から。胆汁が多いと怒りっぽくなると昔は考えられていた→「怒りっぽい・不機嫌な」。', '5eb7692742e18b19'),
  'bin': clear('古英語 binn「かいばおけ・かご」から。物を入れておく入れ物→「大箱・ごみ箱」。', '15f77c4c3ca05045'),
