  'bite': clear('古英語 bītan「かむ」から。歯でかむ→虫が「刺す」、ひと口分→「ひとかじり」。bitter（苦い）と同じ語源。', '3fab8defd2d5eb0d'),
  'bitter': clear('古英語 biter「かみつくような・鋭い」から（bītan「かむ」と同じ語源）。舌をかむような味→「苦い」、心をかむ→「つらい・辛辣な」。', '73c248bfceca240c'),
  'bizarre': clear('フランス語 bizarre「奇妙な」から（イタリア語 bizzarro「怒りっぽい」にさかのぼるとされる）。変わっていて理解しにくい→「奇怪な・異様な」。', 'fcb806c32f00b0de'),
  'blade': clear('古英語 blæd「葉」から。細長く平たい葉の形→刀や道具の「刃」、植物の「葉身」。', 'f18bff818db97494'),
  'bland': clear('ラテン語 blandus「穏やかな・お世辞のうまい」から。刺激がない→「味気ない・当たり障りのない」。', '3511d04f77a8dcff'),
  'blandishment': clear('ラテン語 blandīrī「おだてる」（blandus「口当たりのよい」から）から。耳に心地よい言葉→「甘言・おだて」。bland（当たり障りのない）と同じ語源。', '47c83f282d0a2872'),
  'blank': clear('フランス語 blanc「白い」から。何も書かれていない白さ→「空白の」、表情に何もない→「うつろな」。', '85032e235e035940'),
  'blasphemous': clear('ギリシャ語 blasphēmos「悪口を言う」から。神を悪く言う→「不敬な・冒涜的な」。blame（責める）と同じ語源。', 'a4a8388870b1dbdb'),
  'blasphemy': clear('ギリシャ語 blasphēmia「悪口」から。神や神聖なものを悪く言うこと→「冒涜・神への不敬」。blame（責める）と同じ語源。', '5f397cfb9956a4cc'),
  'blast': clear('古英語 blǣst「強い風のひと吹き」から。強い風→「突風」、激しい空気の噴き出し→「爆発・爆破する」。', '39914bed85381a78'),
  'bleary': clear('中英語 blere「（目が）かすむ」から。涙や眠気で目がぼやける→「（目が）かすんだ・ぼんやりした」。', '02570bddb310da78'),
  'blend': clear('古ノルド語 blanda「混ぜる」から。今と同じ「混ぜる・混合」の意味。', '2d9a3da98f912a33'),
