  'blithe': clear('古英語 blīþe「楽しい・うれしい」から。心配のない楽しさ→「のんきな・陽気な」。bliss（至福）と同じ語源。', '4890b71e5324a00d'),
  'block': clear('古フランス語 bloc「（木の）かたまり」から。道に置いたかたまり→「ふさぐ・妨げる」。', '3078941b08966a15'),
