  'blunder': clear('古ノルド語 blundra「目を閉じる」から。目をつぶったまま進んでつまずく→「へま・大失敗」。', '1e6cbb4a5050c26d'),
  'blunt': clear('中英語 blunt「（刃が）鈍い」から。とがっていない→「鈍い」、飾り気なくずばりと言う→「率直な」。', '9d20a37cd64dfdf1'),
