  'boil': clear('ラテン語 bullīre「泡立つ」から、古フランス語 boillir を経た語。ぶくぶく泡立つ→「沸騰させる・煮る」。', 'c3b7b3d6a2e6f71b'),
  'bolster': clear('古英語 bolster「長いまくら」から。まくらで体を支える→「支える・強化する」。', 'b523f5c15df815f3'),
