  'bombard': clear('フランス語 bombarde「（石の弾を撃つ）昔の大砲」から。ラテン語 bombus「ドーンという音」にさかのぼる。大砲を撃ち込む→「砲撃する」、質問などを次々に「浴びせかける」。bomb（爆弾）と同じ語源。', '3424eca171e97cc8'),
  'bombast': clear('古フランス語 bombace「（服に詰める）綿」から。綿を詰めてふくらませる→中身のない言葉でふくらませる→「大言壮語・美辞麗句」。', 'f9a2899970a865f6'),
  'bonanza': clear('スペイン語 bonanza「穏やかな海・繁栄」から。アメリカで豊かな鉱脈を指すようになり→「大もうけ・思わぬ幸運」。', '92370e1048b99cf8'),
  'boost': clear('19世紀初めのアメリカ英語 boost「押し上げる」から。それより前の由来ははっきりしない。後ろから押す→「高める・後押し」。', '7cc597f5b3234378'),
  'booth': clear('古ノルド語 búð「仮小屋」から。仮に建てた小屋→「屋台・ブース・仕切り席」。', 'a0d908dcc2c730d4'),
  'border': clear('古フランス語 bordure「縁（ふち）」から。土地の縁→「国境・縁」、縁でとなり合う→「接する」。', '547b9c90b804d6ad'),
  'bore': clear('18世紀に使われ始めた bore「うんざりさせる」から。由来ははっきりしない。', '9e91d294dbfe27f3'),
