  'borrow': clear('古英語 borgian「担保を取って貸し借りする」から。約束を担保に物を受け取る→「借りる」。', '25e9c3238323f596'),
  'botch': clear('中英語 bocchen「繕う・修繕する」から。下手な繕い方→「しくじる・下手にやる」。', 'd32d421714c48ddf'),
