  'bow': clear('古英語 būgan「曲げる・曲がる」から。体を曲げる→「お辞儀する」、力に負けて曲がる→「屈する」、曲がった形の「弓」。', 'fb2b11f1d0e3044a'),
  'branch': clear('後期ラテン語 branca「動物の足」から、古フランス語 branche を経た語。胴から足が分かれ出るように→「枝・枝分かれする」。', 'd13a6d3904c8a5b0'),
  'brave': clear('イタリア語 bravo「勇ましい・荒々しい」から、フランス語を経た語。今は「勇敢な」の意味。', '5ef4ccef83e87a72'),
  'brawn': clear('古フランス語 braon「（体の）肉の多い部分」から。たくましい筋肉→「筋力・腕力」。', '9f8ec5abcdf62950'),
  'brazen': clear('古英語 bræsen「真鍮の」から。真鍮のように硬く恥を知らない→「厚かましい・ずうずうしい」。brass（真鍮）と同じ語源。', '8a0032a7489e4b1d'),
  'breed': clear('古英語 brēdan「（子を）育てる」から。子を産ませて育てる→「繁殖させる」、育てて作られた「品種」。brood（ひな）と同じ語源。', 'ba9e2bb349346711'),
  'breeze': clear('スペイン語や古フランス語で「北東の風」を指した brisa から。のちに穏やかな風を指すようになり→「そよ風」。', '6e53f8cd0ee86323'),
  'bride': clear('古英語 brȳd「花嫁」から。今と同じ「花嫁・新婦」の意味。', 'a312fbaea51da01d'),
  'brilliant': clear('フランス語 brillant「輝いている」から（ラテン語 bēryllus「緑柱石」にさかのぼるとされる）。宝石のように輝く→「輝かしい・優秀な」。', '8d9c80a5408ff181'),
  'brink': clear('中低ドイツ語 brink「縁」から。がけなどの縁→今にも落ちそうな所→「瀬戸際」。', 'c62826e418ff0d00'),
  'bristle': clear('古英語 byrst「剛毛」に -le がついた語。動物が怒って毛を逆立てる→「いきり立つ」。', '0466ce8f6a99f11c'),
  'broach': clear('古フランス語 broche「串・きり」から。たるに穴をあけて口を開ける→話の口を開ける→「（話題を）切り出す」。', '7f4cffb53bbdf290'),
