  'brood': clear('古英語 brōd「ひな・子」から。卵を抱いてじっと温める→「卵を抱く」、じっと考え込む→「くよくよ考える」。breed（繁殖させる）と同じ語源。', '9c386a2396c6c427'),
  'broom': clear('古英語 brōm「エニシダ（植物）」から。エニシダの枝を束ねて掃いたことから→「ほうき」。', '65d35267241d8b9a'),
  'browse': clear('古フランス語 brouster「（家畜が）若芽を食べる」から。あちこちの草を少しずつ食べる→本などを「拾い読みする・閲覧する」。', '59c0b8d22718762e'),
  'brush': clear('古フランス語 brosse「ブラシ」から（もとは「小枝のしげみ」を指したとされる）。ブラシでこする→「ブラシをかける」、軽くこする→「軽く触れる」。', '73aa85481deacf6a'),
