  'buckle': clear('ラテン語 buccula「（かぶとの）ほお当て」から、古フランス語 boucle を経た語。ほお当てを留める金具→「留め金・バックル」。', '280b0c5ee160f854'),
  'bucolic': clear('ギリシャ語 boukolos「牛飼い」から。牛飼いの暮らす田舎→「田園の・牧歌的な」。', 'be46600568c96943'),
  'bug': clear('17世紀ごろから使われる bug「虫」から。それより前の由来ははっきりしない。小さな虫がひそむように→機械の「欠陥」、こっそり仕掛ける「盗聴器」。', '7c8afe6a9def993d'),
