  'bully': clear('オランダ語 boel「恋人・兄弟」から。もとは「いとしい人」の意味だったが、「いばる人・ならず者」を経て「いじめっ子・いじめる」になった。', '64de8721cd8cf6e7'),
  'bulwark': clear('中世オランダ語 bolwerc「城壁」から。丸太で組んだ守りの壁→「防壁・とりで」。', '3b423804fe7caed9'),
