  'cabinet': clear('フランス語 cabinet「小部屋」から。大事な物をしまう小部屋→「飾り棚・戸棚」、王が大臣と相談した小部屋→「内閣」。', 'ad7952b9f2f3509e'),
  'cable': clear('中世ラテン語 capulum「なわ」から、古フランス語を経た語。太いなわ→電気を通す「ケーブル・電線」、海底電線で送る「電報」。', '273d1bd366ac71b2'),
  'cadence': clear('ラテン語 cadere「落ちる」から、イタリア語 cadenza を経た語。声や音が上がって落ちる調子→「抑揚・リズム」。', 'f13c4faf69b8b9a7'),
