  'chapel': clear('後期ラテン語 cappella「小さなマント」から。聖マルティヌスのマントを納めた小さな礼拝所の名が広まり→「礼拝堂」。', '206938059d8a79da'),
  'charisma': clear('ギリシャ語 charisma「（神からの）贈り物・恵み」から。生まれつき授かった人を引きつける力→「カリスマ」。', '907b85682991a027'),
  'charlatan': clear('イタリア語 ciarlatano「口のうまい人」（ciarlare「ぺちゃくちゃ話す」から）から。口先で人をだます→「ペテン師・いかさま師」。', 'ef6f18bb59de4a11'),
  'charm': clear('ラテン語 carmen「歌・呪文」から、古フランス語 charme を経た語。呪文で人を引きつける→「魅力」、呪文の力を持つもの→「お守り」。', '98454e27ecbe93d3'),
