  'chasten': clear('ラテン語 castīgāre「正す・罰する」から、古フランス語 chastier を経た語。罰して正しくする→「懲らしめる・（高慢を）くじく」。castigate（厳しく罰する）と同じ語源。', 'aca56fd5ffd83503'),
  'cheat': clear('中英語 cheten「（財産を）没収する」から。役人の不正な没収→人をだまして取る→「だます・カンニングする・詐欺師」。', '75a6e07987948d36'),
