  'chemical': clear('ギリシャ語 chēmeia「錬金術」から（アラビア語を経て alchemy にもなった）。錬金術から生まれた学問→「化学の・化学薬品」。', '74de2280a6276c9f'),
  'chest': clear('ギリシャ語 kistē「箱」から、ラテン語 cista を経た語。大きな箱→「大箱」、あばら骨で囲まれた箱のような部分→「胸」。', 'e4356cf8cd517462'),
