  'church': clear('ギリシャ語 kyriakon「主（神）のもの」から、古英語 cirice を経た語。神の家→「教会」。', '4422cbcfe641d2dc'),
  'cinema': clear('ギリシャ語 kinēma「動き」から、フランス語 cinéma を経た語。動く絵→「映画・映画館」。', '2f196dc2c92e6aa8'),
  'circuitous': clear('ラテン語 circuitus「ぐるりと回ること」（circum「周りを」＋ īre「行く」）から。まっすぐ行かず回り道をする→「遠回りの・回りくどい」。circuit（回路）と同じ語源。', 'ae698ddd7dd8406a'),
  'cite': clear('ラテン語 citāre「呼び出す」から。裁判に人を呼び出す→証拠として言葉を呼び出す→「引用する・挙げる」。', 'bfe74c9a35dd8923'),
  'clandestine': clear('ラテン語 clam「ひそかに」から。人目を避けてこっそり行う→「秘密の・内密の」。', '0c43c4987def6e3b'),
  'clap': clear('古英語 clæppan「打つ・たたく」から。手を打ち合わせる→「拍手する・たたく」。', '733cb33cca50154e'),
  'class': clear('ラテン語 classis「（ローマ市民の）等級・区分」から。同じ区分の集まり→「種類・階級」、一緒に学ぶ集まり→「授業・クラス」。', 'e0fd13a5f4c31ac2'),
  'classic': clear('ラテン語 classicus「最上級の市民の」から。第一級のもの→「名作の・典型的な・古典」。class（等級）と同じ語源。', '7b8ef3aed7e368f2'),
  'clay': clear('古英語 clǣg「粘土」から。今と同じ「粘土」の意味。', '8634450a086c19d2'),
  'clemency': clear('ラテン語 clēmēns「穏やかな・情け深い」から。罰を和らげる穏やかな心→「寛大・温情」。', 'b441909d09e42daf'),
  'clerk': clear('ラテン語 clēricus「聖職者」から。昔は読み書きができるのは主に聖職者だったため、記録をつける人→「事務員・店員」。', 'ffee899a15d4e7a8'),
  'clever': clear('中英語 cliver「すばやくつかむ・器用な」から（由来ははっきりしない）。手先が器用→頭の働きがすばやい→「利口な・巧妙な」。', '3aac5fa398a4c62c'),
  'client': clear('ラテン語 cliēns「（有力者に）頼る人・従う人」から。専門家に頼って仕事を任せる人→「依頼人・顧客」。', '3d77422c28913b07'),
  'climax': clear('ギリシャ語 klimax「はしご」から。はしごを一段ずつ上った最上段→「最高潮・クライマックス」。', 'ad26c6fdaa649aca'),
  'climb': clear('古英語 climban「登る」から。今と同じ「登る・上がる」の意味。', 'bf8301d2953f1711'),
  'cling': clear('古英語 clingan「くっつく」から。しっかりくっついて離れない→「しがみつく・固執する」。', '3d25ce8c27a5d4ee'),
  'cloak': clear('中世ラテン語 clocca「鐘」から。鐘の形に広がるマントを指し→「マント」、体を覆い隠す→「覆い隠す（もの）」。clock（時計）と同じ語源。', '07fa8609ee5fb39d'),
  'clog': clear('中英語 clog「木のかたまり」から。動物の足につけて動きを妨げた木の重り→「詰まらせる・妨げる」。', '264f70334ec67c59'),
  'clot': clear('古英語 clott「かたまり」から。液体が固まってできたかたまり→「凝血・凝固する」。', 'd01077cd52423fa3'),
  'cloth': clear('古英語 clāþ「布」から。今と同じ「布・生地」。clothes（衣服）と同じ語源。', '41dc0b6c8e2c6a1d'),
  'clumsy': clear('中英語 clumsen「（寒さで）かじかむ」から。指がかじかんでうまく動かない→「不器用な・不格好な」。', 'b040349f31f609da'),
  'cluster': clear('古英語 clyster「房」から。ぶどうの房のようにまとまったもの→「集まり・房・群がる」。', '8c17d501c9c0af13'),
  'clutch': clear('古英語 clyccan「（指を）曲げる・握る」から。指を曲げてつかむ→「握りしめる・しがみつく」。', '301dbc2fb51547fa'),
  'coarse': clear('中英語 cors「ふつうの・並の」から（course「いつもの流れ」と同じ語とされる）。上等でない並のもの→「粗い・粗野な」。', 'ab8d869736165c25'),
  'coat': clear('古フランス語 cote「上着」から。体の外側を覆う服→「コート・上着」。', '9796889edcc82c7a'),
