  'cogent': clear('ラテン語 cōgere「駆り集める・強いる」（co-「共に」＋ agere「動かす」）から。相手を納得へと駆り立てる→「説得力のある」。', '8084f1fe108b6acb'),
  'cogitate': clear('ラテン語 cōgitāre「考える」（co-「すっかり」＋ agitāre「あれこれ動かす」）から。頭の中であれこれ動かす→「熟考する」。', '5dfe19ce90e44893'),
  'cognizant': clear('ラテン語 cognōscere「知る」（co-「すっかり」＋ gnōscere「知る」）から。よく知っている→「気づいている・認識している」。recognize（見分ける）と同じ語源。', 'a0923942fd0db527'),
  'collar': clear('ラテン語 collum「首」から。首まわりにつけるもの→「襟・首輪」。', '009e707d337a24e0'),
  'college': clear('ラテン語 collēgium「仲間の団体」（col-「共に」＋ legere「選ぶ」）から。共に学ぶ人の集まり→「大学・単科大学」。colleague（同僚）と同じ語源。', '8fdf1851dbf4b5ca'),
  'colloquial': clear('ラテン語 colloquī「語り合う」（col-「共に」＋ loquī「話す」）から。人と話すときの言葉→「口語の・話し言葉の」。', '753218efb40138bd'),
  'collude': clear('ラテン語 collūdere「いっしょに遊ぶ」（col-「共に」＋ lūdere「遊ぶ」）から。ぐるになって事を運ぶ→「共謀する・結託する」。', 'a887c96b3c3bbff4'),
  'comb': clear('古英語 camb「くし」から。「くし・くしでとかす」、くしの歯のように一か所ずつ探す→「くまなく捜す」。', '956dab5074dea39f'),
  'combat': clear('フランス語 combattre「戦う」（com-「互いに」＋ battre「打つ」）から。互いに打ち合う→「戦闘・格闘・戦う」。battle（戦い）と同じ語源。', '7fb55efa2fbecb6a'),
  'comic': clear('ギリシャ語 kōmikos「喜劇の」（kōmos「お祭り騒ぎ」から）から。笑わせる→「喜劇の」、笑える絵物語→「漫画」。comedy（喜劇）と同じ語源。', '8cf94a6862976ae4'),
  'commodious': clear('ラテン語 commodus「便利な・ちょうどよい」（com-「共に」＋ modus「寸法」）から。寸法がたっぷり合う→「広々とした・ゆったりした」。', '2cecf8e8df6d45f8'),
  'compile': clear('ラテン語 compīlāre「かき集める・奪い取る」から。あちこちから材料を集める→「編集する・まとめる」。', '37b61e85c98cdb9b'),
  'complaisant': clear('フランス語 complaire「人を喜ばせる」から。相手の気に入るようにふるまう→「愛想のよい・人に逆らわない」。complacent（自己満足の）と同じ語源。', '45497c6e1f60550b'),
  'complicity': clear('ラテン語 complex「からみ合った・仲間の」から、フランス語 complice「共犯者」を経た語。悪事にかかわり合っていること→「共謀・加担」。', '0a8b424910eb9cf7'),
  'comport': clear('ラテン語 comportāre「いっしょに運ぶ」（com-「共に」＋ portāre「運ぶ」）から。自分の身を運ぶ→「ふるまう」、互いに合う→「一致する」。', 'b663e01c50c21e33'),
  'compunction': clear('ラテン語 compungere「強く突き刺す」（com-「すっかり」＋ pungere「刺す」）から。良心がちくちく刺される→「良心の呵責・ためらい」。', '2b9da83eba49b981'),
  'conciliatory': clear('ラテン語 conciliāre「結びつける・和解させる」（concilium「集会」から）から。対立する人をまとめる→「融和的な・なだめるような」。council（会議）と同じ語源。', '196dfe7ddf88984e'),
  'condone': clear('ラテン語 condōnāre「（罪を）すっかり許す」（con-「すっかり」＋ dōnāre「与える」）から。過ちをとがめずに許す→「大目に見る・容認する」。donate（寄付する）と同じ語源。', '73c580705b0fc927'),
  'cone': clear('ギリシャ語 kōnos「松かさ」から。松かさの形→「円錐・コーン」。', 'c79fa69e29c8b245'),
