  'congested': clear('ラテン語 congerere「積み重ねる」（con-「いっしょに」＋ gerere「運ぶ」）から。いっぱいに詰め込まれる→「混雑した・うっ血した」。', 'fc5b3668a98d5223'),
  'conjure': clear('ラテン語 coniūrāre「共に誓う」から。神や霊に誓って呼び出す→「魔法で出す・呼び起こす」。', '52ba8df7d53383da'),
  'connive': clear('ラテン語 cōnīvēre「目をつぶる」から。悪いことに目をつぶる→「黙認する・共謀する」。', 'd30394d694f40e43'),
  'connoisseur': clear('フランス語の古い形 connoisseur「よく知っている人」（connaître「知る」から）から。美術品や食べ物をよく知る人→「目利き・鑑定家・通」。', '1994e645a8afd475'),
  'consternation': clear('ラテン語 cōnsternāre「打ちのめす・うろたえさせる」から。驚きで気持ちが乱れること→「うろたえ・狼狽」。', '3455283504f1a47f'),
  'construe': clear('ラテン語 cōnstruere「組み立てる」（con-「共に」＋ struere「積み上げる」）から。言葉を組み立てて意味をとらえる→「（〜と）解釈する・受け取る」。construct（建設する）と同じ語源。', '5878800398e346ad'),
  'consul': clear('ラテン語 cōnsul「執政官」から。古代ローマで国を代表した役職→今は外国で自国民を守る「領事」。', 'a2cd1588174ac8fb'),
  'consult': clear('ラテン語 cōnsultāre「よく考える・相談する」から。人と考えを出し合う→「相談する」、資料に当たる→「調べる」。', 'dd0b5e069f1b66fb'),
  'contaminate': clear('ラテン語 contāmināre「汚す・混ぜて台なしにする」から。有害なものが混ざる→「汚染する」。', '7ded9988ef5c5dc5'),
  'contemplate': clear('ラテン語 contemplārī「じっと見る」（templum「占い師が空を見る区域」から）から。心の中でじっと見つめる→「熟考する」。temple（神殿）と同じ語源。', 'a25aef548e8389c4'),
  'contempt': clear('ラテン語 contemnere「見下す」（con-「すっかり」＋ temnere「軽んじる」）から。価値がないと見下すこと→「軽蔑・侮辱」。', 'e2f4fc56e892cbb1'),
  'contiguous': clear('ラテン語 contingere「触れる」（con-「共に」＋ tangere「触る」）から。境目が触れ合っている→「隣接した・接触している」。contact（接触）と同じ語源。', '99216546f045a2cb'),
  'continue': clear('ラテン語 continuāre「つなぎ合わせる」から（continēre「つなぎとめる」にさかのぼる）。途切れずにつながる→「続く・続ける」。', '7e90f7fa96715935'),
  'contrite': clear('ラテン語 contrītus「すり砕かれた」から。罪の意識で心が砕かれた→「悔いた・悔恨した」。', '9f8db3e549f99611'),
  'contrition': clear('ラテン語 contrītus「すり砕かれた」から。罪の意識で心が砕かれるほどの気持ち→「悔恨・痛悔」。', '3b584f283b08812e'),
  'cookie': clear('オランダ語 koekje「小さなケーキ」から。アメリカに移り住んだオランダ人から広まり→「クッキー」。cake（ケーキ）と同じ語源。', '626c298c1335a3f8'),
  'copper': clear('ラテン語 cuprum「キプロス島の金属」から。キプロス島が銅の産地だったことによる→「銅」。', '4088fc72a68e64a9'),
  'coral': clear('ギリシャ語 korallion「サンゴ」から、ラテン語を経た語。「サンゴ」、その色→「サンゴ色」。', 'bdd00f10c59c1528'),
  'cord': clear('ギリシャ語 chordē「腸・楽器の弦」から、ラテン語 chorda を経た語。弦のような細いひも→「ひも・コード」。chord（和音）と同じ語源。', '96e923057ddf197b'),
  'cork': clear('スペイン語 alcorque「コルク底の靴」から、オランダ語 kurk を経た語とされる。コルクガシの樹皮→「コルク・栓」。', '294f673e33f7549c'),
  'costume': clear('ラテン語 cōnsuētūdō「習慣」から、イタリア語 costume「風習・服装」を経た語。その時代や土地の決まった服装→「衣装・仮装」。custom（習慣）と同じ語源。', '6a6422749212da87'),
  'coterie': clear('フランス語 coterie「（小作人の）組合・仲間」から。気の合う者どうしの小さな集まり→「仲間うち・同人」。', 'b4cb5104aff2e5e1'),
  'cotton': clear('アラビア語 quṭn「綿」から、フランス語 coton を経た語。「綿」、綿の布→「木綿」。', 'e68d4901b97119ea'),
  'couch': clear('古フランス語 couche「寝床」（coucher「横になる」から）から。横になれるいす→「ソファー・長いす」。', 'ae0a2b857b8a65f5'),
  'cough': clear('中英語 coughen「せきをする」から。せきの音をまねて生まれた語とされる。', '4de04bc2cad28cab'),
  'country': clear('古フランス語 contrée「地方」から（ラテン語 contrā「向かい側に」にさかのぼり、目の前に広がる土地を指した）。広がる土地→「国・国土」、町の外に広がる土地→「田舎」。', 'fe30fff893fd7cf5'),
  'coward': clear('古フランス語 couard「臆病者」（coue「しっぽ」から）から。しっぽを巻いて逃げる者→「臆病者」。', '13335915406cb43a'),
  'cozy': clear('スコットランドの cosie「暖かくて気持ちのよい」から。それより前の由来ははっきりしない。', 'af3c86e8df33b866'),
