  'cradle': clear('古英語 cradol「ゆりかご」から。赤ちゃんを育てる所→物事が生まれ育つ「発祥地」。', '02145bbb40a1a8f4'),
  'craft': clear('古英語 cræft「力・技」から。手の技→「技能・工芸」、技で作られた乗り物→「船」。', 'c1359ff8679a5989'),
  'cram': clear('古英語 crammian「詰め込む」から。ぎゅうぎゅう詰める→知識を「一夜漬けする」。', 'e7c5386e28082237'),
  'crane': clear('古英語 cran「ツル（鳥）」から。ツルの長い首に似た機械→「クレーン」、首を長く伸ばす→「首を伸ばす」。', '33373e1d3eb3cd7f'),
  'crass': clear('ラテン語 crassus「厚い・太った・鈍い」から。感覚が鈍くて細やかさがない→「無神経な・露骨な」。', '468e341a37e6f7c8'),
  'crate': clear('ラテン語 crātis「編み枠」から。枝で編んだかご→「木箱・かご・箱詰めする」。', '67db409b346f0090'),
  'crater': clear('ギリシャ語 kratēr「（酒と水を混ぜる）大きなはち」から。はちの形のくぼみ→「噴火口・クレーター」。', '04068bb57a9f59f5'),
  'crave': clear('古英語 crafian「強く求める」から。欲しくてたまらない→「切望する・渇望する」。', '2fe89753b93b5f55'),
  'craven': clear('中英語 cravant「打ち負かされた」から（古フランス語 cravanter「打ち倒す」から来たとされる）。負けを認めて逃げる→「臆病な・卑怯な」。', '76c61180098c271b'),
  'crawl': clear('古ノルド語 krafla「手足でかき進む」から。手足で地面をかいて進む→「這う・のろのろ進む」。', 'd36fc1183c30831c'),
  'cream': clear('古フランス語 cresme「クリーム・聖油」から。牛乳の上に浮く脂肪分→「クリーム」。', '605ee1d0f42b6ff0'),
  'create': clear('ラテン語 creāre「生み出す」から。今までなかったものを生み出す→「創造する」。', 'f524475e5b97ddbc'),
  'credence': clear('ラテン語 crēdere「信じる」から。信じてよいと思う気持ち→「信用・信ぴょう性」。credit（信用）と同じ語源。', 'b23ca3ade3c2b4c9'),
  'credulity': clear('ラテン語 crēdere「信じる」から。何でもすぐに信じてしまうこと→「軽信・だまされやすさ」。', '10cd33ad08ab034b'),
  'creek': clear('古ノルド語 kriki「すみ・曲がり角」から。海岸の奥まった所→「入り江」、アメリカで細い流れ→「小川」。', '9d3a545e9b8fc7f8'),
  'creep': clear('古英語 crēopan「這う」から。体を低くして進む→「這う・忍び寄る」。', 'f398593353d8f174'),
