  'excel': clear('ラテン語 excellere「抜きん出る」（ex-「外へ」＋ -cellere「そびえる」）から。周りより高くそびえる→「秀でる・優れる」。', '703192d4dcb4f524'),
  'excellent': clear('ラテン語 excellere「抜きん出る」（ex-「外へ」＋ -cellere「そびえる」）から。周りより抜きん出ている→「優れた・素晴らしい」。', '7f42967e63c24ff7'),
  'excruciating': clear('ラテン語 excruciāre「ひどく苦しめる」（crux「十字架」から）から。十字架にかけられるような苦しみ→「耐えがたい・激烈な」。cross（十字）と同じ語源。', 'c1c064aacf65eb62'),
