  'facetious': clear('ラテン語 facētus「機知に富む」から、フランス語を経た語。冗談ばかり言う→「おどけた・ふざけた」。', 'ba50abaa0cde7ea0'),
  'facile': clear('ラテン語 facilis「たやすい」（facere「する」から）から。たやすすぎて深みがない→「安易な・うわべだけの」。facility（設備）と同じ語源。', 'befbf53ca9b44adf'),
