  'fake': clear('19世紀の泥棒の隠語から広まった語。ドイツ語 fegen「磨く・掃く」から来たという説があるが、はっきりしない。見た目だけ整える→「偽の・にせの・偽物」。', 'f8c6a57d3bd0de4e'),
