  'hit': clear('古ノルド語 hitta「出くわす・当たる」から、古英語を経た語。ぶつかる→「打つ・たたく・命中する」。', '5175b03da5c75016'),
  'hive': clear('古英語 hȳf「巣箱」から。「ミツバチの巣」、人が群がる所→「密集地」。', 'e57a1c12a8db12f0'),
