  'hose': clear('古英語 hosa「足を覆うもの・長靴下」から。筒状のもの→水を通す「ホース・水をまく」。', '6b977dac7a7434c6'),
  'hostage': clear('古フランス語 hostage「宿泊・（約束の保証に）預けられた人」から。約束を守らせるために預かる人→「人質」。', 'a5c416ff6f99f650'),
  'hostile': clear('ラテン語 hostis「敵」から。敵のような→「敵意のある・敵対的な」。', 'a884064441103a6e'),
