  'hurl': clear('中英語 hurlen「勢いよくぶつける」から（音をまねた語とされる）。「投げつける・強く投げる」。', 'b5d30158ef06f551'),
  'hurricane': clear('スペイン語 huracán から。カリブ海の先住民のことばで嵐の神を指す語にさかのぼる→「ハリケーン・暴風」。', 'bd72061b541461e5'),
  'hurt': clear('古フランス語 hurter「ぶつかる」から。ぶつけてけがをさせる→「傷つける・痛む・痛み」。', '4c1ae553cc96741b'),
