  'hygiene': clear('ギリシャ語 hygiēs「健康な」から、フランス語 hygiène を経た語。健康を保つための技→「衛生・衛生学」。', '903d941ac1275db3'),
  'hymn': clear('ギリシャ語 hymnos「神をたたえる歌」から。「賛美歌・聖歌」。', '10e6de7554f4048a'),
  'hypocrisy': clear('ギリシャ語 hypokrisis「（舞台で）役を演じること」から。本心と違う役を演じる→「偽善」。', '57a046dff69564f3'),
  'hysteria': clear('ギリシャ語 hystera「子宮」から。昔は子宮の病気が原因だと誤って考えられていた→「過度の興奮・ヒステリー」。', '2b723acd0cc984f0'),
