  'icon': clear('ギリシャ語 eikōn「像・似姿」から。聖像→「偶像」、あるものを代表する姿→「象徴」、画面の小さな絵→「アイコン」。', 'c1c41366ad20b44e'),
  'idiot': clear('ギリシャ語 idiōtēs「公の役職をもたない一般人・素人」から。知識のない人→「ばか・まぬけ」。', 'eadb90eae9592c6b'),
  'idle': clear('古英語 īdel「からっぽの・むなしい」から。中身のない時を過ごす→「何もしない・怠惰な・遊んでいる」。', 'ffc507a623056f96'),
  'idol': clear('ギリシャ語 eidōlon「姿・像」から。拝むための像→「偶像」、あこがれて崇める人→「崇拝の対象」。', 'e320b69fcfa29c40'),
  'idyllic': clear('ギリシャ語 eidyllion「（田園を描いた）短い詩」から。詩に描かれるような→「牧歌的な・のどかな」。', '3ed7434513bc5d2d'),
  'if': clear('古英語 gif「もし」から。「もし〜なら」。', '370b75d81da7df94'),
  'ill': clear('古ノルド語 illr「悪い」から。「悪い」、体の具合が悪い→「病気の」。', '0c093326d94831de'),
