  'line': clear('ラテン語 līnea「亜麻糸・線」（līnum「亜麻」から）から、古英語 line を経た語。糸のように細長いもの→「線・列」、つながり→「系統」、台本の一行→「セリフ」。linen（亜麻布）と同じ語源。', 'afd53ed2ebed82c3'),
  'linen': clear('古英語 līnen「亜麻の」（ラテン語 līnum「亜麻」から）から。亜麻の糸で織った布→「リネン・亜麻布」。line（線）と同じ語源。', 'f7bc80c7c628771c'),
  'link': clear('古ノルド語 hlenkr「鎖の輪」から。輪と輪をつなぐ→「つながり・連結する・関連づける」。', '9c34bfa778c371d0'),
  'lip': clear('古英語 lippa「唇」から。「唇」。', 'b61a1f65eb8a8db4'),
  'liquid': clear('ラテン語 liquidus「流れる・澄んだ」（liquēre「液体である」から）から。流れる物→「液体・液体の」。', '604bca141ffa3d7a'),
  'list': clear('「縁・細長い帯」を表すゲルマン系の語から（古英語 līste も同じ語）。イタリア語・フランス語で、細長い紙に名前を書き並べたものを指すようになった→「リスト・一覧」。', '289de071e7e326d0'),
  'lithe': clear('古英語 līþe「柔らかい・穏やかな」から。体が柔らかい→「しなやかな・柔軟な」。', '591dcd2183e8bb6c'),
  'litter': clear('古フランス語 litiere「寝床・寝わら」（ラテン語 lectus「寝台」から）から。家畜の寝わらが散らばる→「ごみ・散らかす」、寝床で一度に生まれる子→「（動物の）一腹の子」。', '64cc4c4bcaaaa165'),
  'little': clear('古英語 lȳtel「小さい・少ない」から。「小さい・少しの」。', '58c44c015821272d'),
  'load': clear('古英語 lād「運ぶこと・道」から。運ぶもの→「荷・積む・詰める」。', '45cb547377b4a062'),
  'loaf': clear('古英語 hlāf「パン」から。「（パンの）ひとかたまり」。「のらくらする」の loaf は loafer（なまけ者）から後で作られた別の語とされる。', '7d9f2d9e9115818d'),
  'loath': clear('古英語 lāþ「憎い・嫌な」から。嫌だと思う→「気が進まない・いやがって」。loathe（嫌悪する）と同じ語源。', '215e67a8fea65f7b'),
  'loathe': clear('古英語 lāþian「嫌う」（lāþ「憎い」から）から。「嫌悪する・ひどく嫌う」。loath（気が進まない）と同じ語源。', 'bae581fe05970ce0'),
  'lobby': clear('中世ラテン語 lobia「屋根つきの通路・回廊」から。建物の入り口の広間→「ロビー」、議会のロビーで議員をつかまえて頼みこむ人たち→「圧力団体・働きかける」。', '9245d9012979e2e9'),
  'lodge': clear('古フランス語 loge「小屋・あずまや」から。「山小屋」、小屋に泊める→「宿泊する」、苦情をしかるべき所に置く→「（苦情を）申し立てる」。', '4531f233b3af37dd'),
  'log': clear('中英語 logge「丸太」から。「丸太」、丸太を海に流して船の速さを測り、その結果を書き留めた→「記録・記録する」。', '62afa26722c96372'),
  'logic': clear('ギリシャ語 logos「ことば・理性」から（logikē「推論の技術」）。筋道の通った考え方→「論理・理屈」。', '903776e0ba4d7b50'),
  'loiter': clear('中世オランダ語 loteren「ぐらつく・ぶらぶらする」から。あてもなくぶらぶらする→「うろつく・たむろする」。', 'a348f3b9db694e0f'),
  'loop': clear('中英語 loup「輪」から。それより前の由来ははっきりしない。「輪・ループ・輪にする」。', '5f43552024213d98'),
