  'lord': clear('古英語 hlāfweard「パンを守る人」（hlāf「パン」＋ weard「番人」）から。家の者にパンを与える主人→「主君・領主・卿」。lady（婦人）と対になる語。', 'e0e172ba106814d9'),
  'lost': clear('古英語 losian「失う・なくなる」から来た lose の過去分詞。失われた→「迷った・負けた」。', 'fdcb043e987fda1d'),
  'low': clear('古ノルド語 lágr「低い」から。「低い」、値段が低い→「安い」、気持ちが低い→「元気のない」。', '7483524edc8144a7'),
  'luck': clear('中世オランダ語 luc「幸運」から（賭け事のことばとして入ったとされる）。「運・幸運」。', '72ea52875514e47a'),
  'lugubrious': clear('ラテン語 lūgēre「嘆く・喪に服す」から。嘆き悲しんでいる様子→「陰気な・物悲しい」。', '276a2586e57225d4'),
  'lull': clear('中英語 lullen「（子どもを）あやす」から（あやす声をまねた語）。「寝かしつける・なだめる」、騒ぎがしずまる間→「小休止」。', 'f310eef23ce0b4a5'),
  'lump': clear('中英語 lumpe「かたまり」から。「かたまり・こぶ」、ひとかたまりにする→「ひとまとめにする」。', '42f8ed779ed61dde'),
  'lunar': clear('ラテン語 lūna「月」から。「月の」、月の満ち欠けで数える暦→「太陰の」。', '8f6eabac94f16b77'),
  'lure': clear('古フランス語 loirre「おとり」から。鷹狩りで鷹を呼び戻すための鳥の形のおとり→「誘い込む・おびき寄せる・誘惑」。', '8e247fd014c96153'),
  'lurid': clear('ラテン語 lūridus「青白い・黄ばんだ」から。ぎらぎらした不気味な色→「どぎつい・けばけばしい」。', '8ebfa63b7dd23b36'),
  'lurk': clear('中英語 lurken「ひそむ」から（北欧系の語とされる）。「潜む・待ち伏せる」。', '23caa05904c7077e'),
  'lush': clear('中英語 lusch「柔らかい・ゆるんだ」から。みずみずしく柔らかい草木→「青々と茂った・豊かな」。', 'aace99123ada5184'),
  'luxury': clear('ラテン語 luxus「度を越すこと」から（luxuria「ぜいたく」）。必要以上にお金をかける→「ぜいたく・豪華」。', 'dbd724979cbecf96'),
  'mail': clear('古フランス語 male「袋・かばん」から。手紙を入れて運ぶ袋→「郵便・郵送する」。', '9b6f26c863235911'),
  'major': clear('ラテン語 major「より大きい」（magnus「大きい」の比較級）から。より大きい方の→「主要な・重大な」。mayor（市長）と同じ語源。', '43f5fcc613d86c8b'),
  'malady': clear('ラテン語 male habitus「具合が悪い」（male「悪く」＋ habitus「状態の」）から、古フランス語 maladie を経た語。「病気」、社会の病→「（社会の）弊害」。', 'c6cf4cf5043ec19d'),
  'male': clear('ラテン語 masculus「男の」から、古フランス語 masle を経た語。「男性・雄・男性の」。masculine（男性の）と同じ語源。', '3f6014e3bc3cc410'),
  'malfeasance': clear('フランス語 malfaisance「悪事」（mal「悪く」＋ faire「する」）から。悪いことをすること→「不正行為・違法行為」。', 'ee2f9deab57887ac'),
  'malign': clear('ラテン語 malignus「悪意のある」（malus「悪い」から）から。悪意をもって言う→「中傷する・悪く言う」。malignant（悪性の）と同じ語源。', 'b0fcb4a2fc59e0da'),
  'malleable': clear('ラテン語 malleus「つち・ハンマー」から。つちでたたいて形を変えられる→「（金属が）展性のある」、考えが変わりやすい→「順応性のある」。', '6626517d6cd574e2'),
  'mammal': clear('ラテン語 mamma「乳房」から。乳で子を育てる動物→「哺乳類」。', '71f40a365724a0c7'),
