  'noble': clear('ラテン語 nōbilis「知られた・名高い」（nōscere「知る」から）から。世に知られた家柄→「高貴な」、心が立派な→「気高い」。', 'cc3e011422ebbf49'),
  'nod': clear('中英語 nodden「頭を下げる」から。それより前の由来ははっきりしない。「うなずく・会釈する・うなずき」。', 'd9216324dcc93c8a'),
  'nomad': clear('ギリシャ語 nomas「牧草地を渡り歩く人」（nemein「放牧する」から）から。「遊牧民・放浪者」。', '9c869098ac10f129'),
  'nonchalant': clear('フランス語 nonchalant「気にかけない」（non-「〜でない」＋ chaloir「気にかける」）から。「無頓着な・平然とした」。', '937f4629dc0ef823'),
