  'null': clear('ラテン語 nūllus「何もない」（ne-「〜でない」＋ ūllus「どれか」）から。何もない→「ゼロの」、効力が何もない→「無効の」。', 'd09ccac8458bb892'),
  'numb': clear('中英語 nomen「つかまれた・奪われた」（古英語 niman「取る」の過去分詞）から。寒さなどに感覚を奪われた→「感覚のない・しびれた」。b は後の時代につづりに加わった。', '279cda01e0f4ab49'),
  'oak': clear('古英語 āc「オーク」から。「オーク・樫（かし）の木」。', '5e36c3791b3db628'),
  'oasis': clear('ギリシャ語 oasis「肥えた土地」から（エジプトのことばにさかのぼる）。砂漠の中で水と緑のある所→「オアシス」、心が休まる所→「憩いの場」。', '4bddf3abd97e784b'),
  'oath': clear('古英語 āþ「誓い」から。「誓い・宣誓」。', 'fe054cd4e529a141'),
  'obdurate': clear('ラテン語 obdūrāre「固くする」（ob-「すっかり」＋ dūrus「固い」）から。心を固くして動かない→「頑固な・かたくなな」。durable（長持ちする）と同じ語源。', 'e708d8c67c18035e'),
  'obesity': clear('ラテン語 obēsus「食べて太った」（ob-「すっかり」＋ edere「食べる」）から。「肥満」。', 'f3d13c85b3609f79'),
  'oblique': clear('ラテン語 oblīquus「斜めの」から。「斜めの」、まっすぐ言わない→「遠回しの」。', '2f74a749bc001f12'),
  'oblivious': clear('ラテン語 oblīvīscī「忘れる」から。忘れてしまっている→「気づかない・忘れて」。', '8aa2a7377871918d'),
  'obscene': clear('ラテン語 obscēnus「不吉な・忌まわしい」から。人前に出すべきでない→「わいせつな・下品な」。', 'd5e5d8414ff04bb1'),
  'obscure': clear('ラテン語 obscūrus「暗い・覆われた」から。暗くてよく見えない→「あいまいな」、世に知られていない→「無名の」。', '629f54cfc4b1cbd2'),
  'obsequious': clear('ラテン語 obsequī「言いなりに従う」（ob-「〜に向かって」＋ sequī「ついて行く」）から。相手にどこまでもついて従う→「こびへつらう・追従的な」。sequence（連続）と同じ語源。', '5d8da2ba240c1f2f'),
  'obtuse': clear('ラテン語 obtūsus「たたいて鈍くした」（obtundere「打ちつける」から）から。刃先が鈍い→「（角が）鈍い」、頭の働きが鈍い→「鈍感な」。', 'a48338777348bc60'),
  'obviate': clear('ラテン語 obviāre「道で立ちふさがる」（ob-「〜に向かって」＋ via「道」）から。問題の行く手を先にふさぐ→「（必要・危険を）未然に防ぐ・取り除く」。obvious（明らかな）と同じ語源。', 'acb424cab0d5511a'),
  'odd': clear('古ノルド語 oddi「とがった先・三角形・端数」から。二つの点と三つ目の余った点→「奇数の・（対の）片方の」、ふつうから外れた→「奇妙な」。', 'fd566ac8ae6b140e'),
  'odious': clear('ラテン語 odium「憎しみ」から。憎しみを買う→「憎むべき・忌まわしい」。', '54861fbf698fbb88'),
  'of': clear('古英語 of「〜から・離れて」から。「〜から」→「〜の」。off（離れて）と同じ語源。', '98bdfc08440b88de'),
  'off': clear('古英語 of「〜から離れて」を強く発音した形から。「離れて」、つながりが離れる→「（電源を）切って」。of（〜の）と同じ語源。', '706eea2905a76116'),
  'offend': clear('ラテン語 offendere「ぶつかる・つまずく」（ob-「〜に向かって」＋ -fendere「打つ」）から。人の気持ちにぶつかる→「怒らせる・感情を害する」、決まりにぶつかる→「違反する」。', 'a7fa6cd99a55e1cf'),
  'on': clear('古英語 on「上に・中に」から。「〜の上に・〜に」。', '3d3e3f77c0f7360f'),
  'one': clear('古英語 ān「1つ」から。「1つ（の）」、だれか一人→「（漠然と）人」。冠詞の an・a と同じ語源。', 'e4801dcc7f3fb8e1'),
  'onerous': clear('ラテン語 onus「重荷」から。重荷になる→「重荷となる・厄介な」。', '147c12adf6536b1d'),
  'onion': clear('ラテン語 ūniō「一つの玉ねぎ・真珠」（ūnus「1つ」から）から、古フランス語 oignon を経た語。一つにまとまった玉→「玉ねぎ」。', '8241dd23f77fc083'),
  'opaque': clear('ラテン語 opācus「陰になった・暗い」から。光を通さない→「不透明な」、意味が見通せない→「不明瞭な」。', 'b426b0cca112c2a5'),
  'open': clear('古英語 open「開いた」から（up「上へ」と関係する語とされる）。「開いた・開ける」。', '75c02bdca4f3ef8f'),
