  'optimistic': clear('ラテン語 optimus「最もよい」から。この世は考えうる最もよい世界だとする考え方→「楽観的な」。', 'ea24818e6bd75a79'),
  'opulent': clear('ラテン語 opulentus「富んだ」（ops「富・力」から）から。「富裕な・豪華な」。', '9527a64ea599f644'),
  'or': clear('中英語 or「または」から（古英語 oþþe「または」の変化した形とされる）。「または・あるいは」。', '47c3a01ff64602ce'),
  'orbit': clear('ラテン語 orbita「車輪の跡・通り道」（orbis「輪」から）から。回ってできる通り道→「軌道・周回する」。', 'baaba6fcea48bd99'),
  'orchard': clear('古英語 ortgeard「菜園」から（後半の geard は yard「庭・囲い地」と同じ語）。囲いの中に植えた庭→「果樹園」。', '9a8f4dc62c5bb11d'),
  'orchestra': clear('ギリシャ語 orkhēstra「（劇場で）合唱隊が踊る舞台前の場所」（orkheisthai「踊る」から）から。舞台前で演奏する楽団の場所→「オーケストラ・管弦楽団」。', '270abc0cf6bea88e'),
  'order': clear('ラテン語 ōrdō「列・順序」から、古フランス語を経た語。「順序」、きちんと並ばせる→「命令」、品物をそろえてもらう→「注文」。', '574f503077b253b5'),
  'ore': clear('古英語 ār「銅・真ちゅう」から（ōra「掘り出した金属」と混ざった）。「鉱石」。', '2597e90fa5ee07e3'),
  'orient': clear('ラテン語 oriēns「昇っている（太陽）」（orīrī「昇る」から）から。日の昇る方角→「東洋」、東の方角を基準に向きを決める→「方向づける・適応させる」。', '91bb19f9f4a7b63b'),
  'orphan': clear('ギリシャ語 orphanos「親を失った」から。「孤児・孤児にする」。', '3bd1284a33828aec'),
  'oscillate': clear('ラテン語 ōscillāre「揺れる」（ōscillum「木につるして揺らした小さな人形」から）から。「振動する・揺れ動く」。', '6580386cc7ee436e'),
  'ostensible': clear('ラテン語 ostendere「見せる・示す」から。人に見せるための→「表向きの・うわべの」。', '5af7d1c3b7db7501'),
  'ostentatious': clear('ラテン語 ostentāre「見せびらかす」（ostendere「見せる」から）から。「これ見よがしの・派手な」。ostensible（表向きの）と同じ語源。', '70684fc52365d93f'),
  'ostracize': clear('ギリシャ語 ostrakon「陶器のかけら」から。古代アテネで、追放したい人の名を陶片に書いて投票した→「排斥する・仲間外れにする」。', '411ddb680720c03b'),
  'ounce': clear('ラテン語 uncia「12分の1」から、古フランス語を経た語。1ポンドの12分の1とした重さ→「オンス」、ごく少ない量→「ほんの少し」。inch（インチ）と同じ語源。', '5c78c5fa225c5e2b'),
  'oust': clear('古フランス語 oster「取り除く」から。地位から取り除く→「追放する・失脚させる」。', 'a3c8d5d99ccc38ef'),
  'out': clear('古英語 ūt「外へ」から。「外へ・外に」。', '740274a7ebcb3c28'),
