  'pack': clear('中低ドイツ語 pak「包み・荷」から。「包み・荷造りする・詰める」、ひとまとまりの動物→「群れ」。', '8517ff6daa0f5f1c'),
  'paddle': clear('中英語 padell「小さなへら」から。それより前の由来ははっきりしない。へらのような道具→「パドル・かい・水をかく」。', '9fd83933c55f3180'),
