  'palatable': clear('ラテン語 palātum「口の天井（口蓋）・味覚」から。味覚に合う→「口に合う」、考えが受け入れやすい→「受け入れやすい」。', '3a4f3e633c1b9750'),
  'palatial': clear('ラテン語 palātium「宮殿」から（ローマのパラティヌスの丘に皇帝の宮殿があったことによる）。「宮殿のような・壮麗な」。palace（宮殿）と同じ語源。', 'a7cdd42ac3900a49'),
  'palliative': clear('ラテン語 palliāre「マントで覆う」（pallium「マント」から）から。病気のもとは治さず症状を覆い隠す→「緩和剤」、問題を覆うだけ→「その場しのぎ」。', 'f526429d64cb67d3'),
  'pallid': clear('ラテン語 pallidus「青白い」から。「青白い・生気のない」。pale（青白い）と同じ語源。', '6696757f84d64c4f'),
  'palm': clear('ラテン語 palma「手のひら・ヤシ」から。「手のひら」、広げた手のような葉をもつ木→「ヤシの木」。', '134bfe95c69f581b'),
  'palpable': clear('ラテン語 palpāre「そっと触る」から。手で触れられるほどの→「触れられそうな・明白な」。', 'a72ce18c9253875f'),
  'paltry': clear('低地ドイツ語 paltrig「ぼろぼろの」（palte「ぼろ切れ」から）から来たとされる。ぼろ切れのような→「ささいな・わずかな」。', '6e26e303b169920f'),
  'pamper': clear('中世オランダ語 pamperen「食べ物を詰め込む」から来たとされる。食べ物を与えすぎる→「甘やかす・大事に扱う」。', '7b6666a5046d722e'),
  'pamphlet': clear('中英語 Pamflet から。12世紀に広く読まれた短いラテン語の恋愛詩『パンフィルス』の呼び名で、薄い冊子を指すようになった→「パンフレット・小冊子」。', '2ac06bfb1459e896'),
  'panacea': clear('ギリシャ語 panakeia「すべてを治すもの」（pan-「すべて」＋ akos「治療」）から。「万能薬」、どんな問題も解く→「万能の解決策」。', '91e7402e21b9d1d0'),
  'pane': clear('ラテン語 pannus「布切れ」から、古フランス語 pan「布の一片・区画」を経た語。区切られた一枚→「窓ガラス・一区画」。panel（パネル）と同じ語源。', '386745b9f05fa6e3'),
  'panel': clear('古フランス語 panel「布切れ・小さな区画」（ラテン語 pannus「布切れ」から）から。区切られた板→「パネル・羽目板」、陪審員の名を書いた紙片→「審査員団」。', 'bdeb93848b1f0daf'),
  'pant': clear('古フランス語 pantaisier「息を切らす・うなされる」から。「あえぐ・息を切らす」。', 'e113eb7e59750a98'),
