  'parade': clear('スペイン語 parada「止まること・隊列」（parar「止める・整える」から）から、フランス語を経た語。整列した隊列を見せる→「パレード・行進」。', 'e69e33da2428cb68'),
  'paragon': clear('イタリア語 paragone「試金石（金の質を試す石）」から。ほかを比べる基準になるほど優れたもの→「模範・典型」。', 'fdcd86c24f218534'),
  'paralysis': clear('ギリシャ語 paralysis「（体の片側が）ゆるむこと」（para-「横に」＋ lyein「ゆるめる」）から。体が動かなくなる→「まひ」、組織が動かなくなる→「無力状態」。', '08236d97e1a65ce2'),
  'pariah': clear('タミル語 paraiyar「太鼓をたたく人」から。祭りで太鼓をたたいた人々が南インドで低い身分とされたことから→「のけ者・社会的追放者」。', '16a1eda150caf2f4'),
  'park': clear('古フランス語 parc「囲い地・猟場」から。囲われた土地→「公園」、車を囲いに入れて置く→「駐車する」。', 'b558dd783f9eff73'),
