  'particular': clear('ラテン語 particula「小さな部分」（pars「部分」から）から。一部分に限った→「特定の・特別な」、細かい点にこだわる→「好みのうるさい」。', '48a7b07f3099e0f0'),
  'partisan': clear('イタリア語 partigiano「党派の人・支持者」（parte「部分・党派」から）から。一方の側につく→「党派的な・一方に肩入れする」。party（党）と同じ語源。', '385c82fd78aeb11e'),
  'party': clear('ラテン語 pars「部分」から、古フランス語 partie「分けたもの・側」を経た語。人の集団の一部→「政党・一行」、人の集まり→「パーティー」。', '9fbb2a5a30d1df9c'),
  'passport': clear('フランス語 passeport「港を通る許可」（passer「通る」＋ port「港」）から。国を出入りする許可証→「パスポート・旅券」。', 'ac488d591266a536'),
  'paste': clear('ギリシャ語 pastē「大麦のかゆ」から、ラテン語・古フランス語を経た語。練った柔らかいもの→「のり・ペースト」、のりで貼る→「貼り付ける」。pasta（パスタ）と同じ語源。', 'e19da3ba1bae1239'),
  'pasture': clear('ラテン語 pāscere「（家畜に）食べさせる」から、古フランス語を経た語。家畜に草を食べさせる場所→「牧草地」。pastor（牧師）と同じ語源。', '0f7d3e5220a27bca'),
  'patch': clear('中英語 pacche「布切れ」から。それより前の由来ははっきりしない。穴をふさぐ布→「継ぎ当て・継ぐ」、小さな一区切り→「小区画」、不具合をふさぐ→「修正」。', 'a2f32ffae3d10ff4'),
  'patent': clear('ラテン語 patēre「開いている」から。だれでも読めるよう開いたまま出す公文書→王が権利を与える文書→「特許・特許の」。', '57a397c24fb6cbf0'),
