  'pattern': clear('ラテン語 patrōnus「後ろ盾」から、中英語 patron「手本」を経た語。まねるべき手本→「型・模様」、繰り返される型→「傾向」。patron（後援者）と同じ語から分かれた。', '0233d0fc3c8c2f22'),
