  'pause': clear('ギリシャ語 pausis「止めること」（pauein「止める」から）から、ラテン語を経た語。「一時停止する・間を置く・休止」。', 'b0ec3608cb6eed91'),
  'pave': clear('ラテン語 pavīre「打って固める」から、古フランス語 paver を経た語。道の土を固めて石を敷く→「舗装する」、道を平らにする→「（…への）道を開く」。', '0191ecbe170d0171'),
  'pawn': clear('古フランス語 pan「担保・質」から。「質草・質に入れる」。チェスの「歩」の pawn は古フランス語 peon「歩兵」（ラテン語 pēs「足」にさかのぼる）から来た別の語で、そこから「手先」の意味が出た。', '320d90358f04695a'),
