  'peasant': clear('古フランス語 paisant「田舎の人」（pays「田舎・土地」から）から。土地を耕す人→「農民・小作農」。', 'f5ebee68baf4e9e0'),
  'pebble': clear('古英語 papolstān「小石」から。それより前の由来ははっきりしない。「小石・玉石」。', '42036fcd9655039a'),
  'pedantic': clear('イタリア語 pedante「家庭教師・学校の先生」から。先生のように細かい知識をひけらかす→「学者ぶった・細かいことにうるさい」。', 'd74e9712bbdeb110'),
  'peek': clear('中英語 piken「のぞく」から。それより前の由来ははっきりしない。「のぞき見る・ちらっと見る」。', '056e921904c55037'),
  'peel': clear('古英語 pilian「皮をむく」（ラテン語 pilāre「毛を抜く」から）から。「皮をむく・はがれる・皮」。', '55f7f4f655b90361'),
  'peep': clear('中英語 pepen「のぞく」から（peek と関係する語とされる）。「のぞく・ちらりと見える」。', '540ec6a0e621f5f4'),
  'peg': clear('中英語 pegge「くぎ・くい」から（中世オランダ語から入ったとされる）。「掛けくぎ・留めくい」、くいで留める→「固定する」。', 'a90c2808eddce70e'),
  'pejorative': clear('ラテン語 pējor「より悪い」から。悪く言う→「軽蔑的な・けなす」。impair（損なう）と同じ語源。', 'aa06052b28a0d1e8'),
