  'penury': clear('ラテン語 pēnūria「欠乏」から。「極貧・欠乏」。penurious（極貧の）と同じ語源。', '90fe29ba60474e9b'),
  'percent': clear('ラテン語 per centum「100につき」（per「〜につき」＋ centum「100」）から。「パーセント・百分率」。century（100年）と同じ語源。', 'f902ca0c1c87cd91'),
  'perch': clear('ラテン語 pertica「さお・棒」から、古フランス語 perche を経た語。鳥が止まる棒→「止まり木」、そこに止まる→「止まる・（高い所に）座る」。', '078460cd55fc7d21'),
  'perform': clear('古フランス語 parfournir「すっかり成し遂げる」（par-「すっかり」＋ fournir「果たす」）から。やり遂げる→「行う」、舞台でやってみせる→「演じる」。つづりは form（形）に引き寄せられたもので、form から作った語ではない。', '506d0e636b45e233'),
  'perfunctory': clear('ラテン語 perfungī「済ませる」（per-「すっかり」＋ fungī「務めを果たす」）から。とにかく済ませるだけの→「おざなりの・形式だけの」。function（機能）と同じ語源。', 'ba56c1a40f1d4a0a'),
  'perpetrate': clear('ラテン語 perpetrāre「やり遂げる」（per-「すっかり」＋ patrāre「成し遂げる」）から。悪いことをやってのける→「（罪を）犯す・しでかす」。', 'b4e232315a1edfad'),
  'perpetrator': clear('ラテン語 perpetrāre「やり遂げる」から。悪事をやってのけた人→「加害者・犯人」。perpetrate（犯す）と同じ語源。', '6139fbb767b103c8'),
  'perpetual': clear('ラテン語 perpetuus「途切れずに続く」から。ずっと続く→「永続する・絶え間ない」。', '4a9cf7ad4d05fd14'),
  'perplex': clear('ラテン語 perplexus「もつれた・入り組んだ」（per-「すっかり」＋ plectere「編む」）から。頭の中がもつれる→「当惑させる・困惑させる」。', 'a7b699f22cb6da31'),
  'perspicacious': clear('ラテン語 perspicere「見通す」（per-「通して」＋ specere「見る」）から。物事の奥まで見通す→「洞察力の鋭い・明敏な」。', 'b7f549ac5b40e99b'),
  'pessimistic': clear('ラテン語 pessimus「最も悪い」から。物事を最も悪い方に考える→「悲観的な」。optimistic（楽観的な）と対になる語。', '4025c9b4232b412e'),
  'pest': clear('ラテン語 pestis「疫病」から、フランス語 peste を経た語。災いをもたらすもの→「害虫・厄介者」。', '294e3d9bcb877200'),
  'petal': clear('ギリシャ語 petalon「葉・薄い板」から。花の中の薄い葉のようなもの→「花びら」。', 'a4ab91277312d896'),
  'petulant': clear('ラテン語 petulāns「生意気な・向こう見ずな」（petere「襲いかかる」から）から。すぐ突っかかる→「不機嫌な・短気な」。', 'e1de6649b1c325f2'),
  'pharmacy': clear('ギリシャ語 pharmakon「薬」から。薬を扱うこと→「調剤・薬局」。', 'cbd9e7276ead718f'),
