  'phlegmatic': clear('ギリシャ語 phlegma「粘液」から。昔、体の中の粘液が多い人は冷静で感情が動きにくいと考えられた→「冷静沈着な・無感動な」。', '6eb89c07c26a6981'),
  'phobia': clear('ギリシャ語 phobos「恐れ」から。「恐怖症」。', '1a51c3f071be5b88'),
  'phrase': clear('ギリシャ語 phrasis「言い方・話し方」（phrazein「言う」から）から。ことばの言い回し→「言い回し・語句・言い表す」。', '51fd27c6c95d66a8'),
  'pick': clear('中英語 picken「つつく」から。つついて取る→「摘む」、よいものを取る→「選ぶ」。', 'c1c033ae7c5a4122'),
  'piece': clear('古フランス語 piece「かけら」から（ガリアのことばにさかのぼるとされる）。「断片・一片」、ひとまとまりの作り物→「作品」。', '4ea8f94aedf6a1d5'),
  'pier': clear('中世ラテン語 pera「橋げたを支える石積み」から。「橋脚」、海に突き出た台→「桟橋・埠頭」。', '7ad349836f50025a'),
  'pierce': clear('古フランス語 percer「突き通す」から。「貫く・突き刺す」。', '6492f9c1e2fdccc8'),
  'pile': clear('ラテン語 pīla「柱・石積み」から、古フランス語を経た語。積み上げた山→「積み重ね・山・積み上げる」。pillar（柱）と同じ語源。', 'a862f86ab4dceda5'),
  'pillar': clear('ラテン語 pīla「柱」から、古フランス語 piler を経た語。「柱・支柱」。pile（積み重ね）と同じ語源。', '08fa3e98f0d912c6'),
  'pillow': clear('ラテン語 pulvīnus「クッション」から、古英語 pyle を経た語。「枕」。', '4681c15c8e3aeaa9'),
