  'pioneer': clear('フランス語 pionnier「道を切り開く歩兵」（古フランス語 peon「歩兵」から）から。軍の先頭で道を切り開く兵→「開拓者・先駆者・先駆ける」。', '84428a41a35987ca'),
  'pious': clear('ラテン語 pius「務めを大切にする・信心深い」から。「敬虔な・信心深い」。', '1cf6bc4207f66d3b'),
