  'supplant': clear('ラテン語 supplantāre「足払いをかける」（sub-「下から」＋ planta「足の裏」）から。足をすくって倒し、その場を取る→「取って代わる・地位を奪う」。', 'f4d41e7e4f796a0d'),
  'supple': clear('ラテン語 supplex「ひざを曲げて頼む」から、古フランス語 souple を経た語。よく曲がる→「しなやかな・柔軟な」。', '364ade33727e926a'),
