  'surveillance': clear('フランス語 surveiller「上から見張る」（sur-「上から」＋ veiller「見張る」）から。「監視・見張り」。vigil（寝ずの番）と同じ語源。', '8f7d2b4e7950a20c'),
  'svelte': clear('イタリア語 svelto「引き抜かれた・すらりとした」から、フランス語を経た語。「すらりとした・ほっそりした」。', '40d49e9c8e2c1a5a'),
  'swab': clear('低地ドイツ語 swabber「（甲板を洗う）モップ」から、後ろを削って作られた語。モップでふく→「ふき取る」、小さなふき取り道具→「綿棒・綿棒で採る」。', 'f2c9c6dcfe22c2a1'),
  'swamp': clear('低地ドイツ語 swamp「海綿・スポンジ」から来たとされる。水を吸った土地→「沼地・湿地」、水が押し寄せるように→「殺到する」。', 'cbf2340618f7eed2'),
  'swan': clear('古英語 swan「白鳥」から。「白鳥」。', 'b2222c2e95b43d0d'),
