  'sway': clear('中英語 sweyen「揺れ動く」から（北欧系の語とされる）。「揺れる・揺らす」、人の気持ちを揺り動かす→「左右する」。', 'bc8429f09a282ca3'),
  'swear': clear('古英語 swerian「誓う」から。神にかけて誓う→「誓う」、神の名をみだりに口にする→「ののしる」。', '2f196abff47b018c'),
