  'sycophantic': clear('ギリシャ語 sȳkophantēs「密告者」（sȳkon「イチジク」＋ phainein「示す」）から。人を訴えて取り入る者→「こびへつらう・追従的な」。', '085305b90ef673e8'),
  'syllable': clear('ギリシャ語 syllabē「ひとまとめに取ったもの」（syn-「一緒に」＋ lambanein「取る」）から。いくつかの音をひとまとめにしたもの→「音節」。', '37698277dcb8e474'),
  'syllabus': clear('ギリシャ語 sittyba「（巻物の）見出し札」の書き誤りから生まれた後期ラテン語 syllabus「目録」から。授業の中身の一覧→「講義概要・シラバス」。', '0a26f984aeddb015'),
  'synergy': clear('ギリシャ語 synergos「一緒に働く」（syn-「一緒に」＋ ergon「仕事」）から。力を合わせて働くことで生まれる効果→「相乗効果」。energy（エネルギー）と同じ語源。', '5f57954bead2da25'),
  'syrup': clear('アラビア語 sharāb「飲み物」から、中世ラテン語・古フランス語を経た語。甘い飲み薬→「シロップ・糖蜜」。', '47cedcdd9e2b84a4'),
  'system': clear('ギリシャ語 systēma「組み合わせたもの」（syn-「一緒に」＋ histanai「立てる」）から。組み合わせて一つにしたもの→「系統・体系・制度」。', '6a74febbc2934b57'),
  'tackle': clear('中低ドイツ語 takel「（船の）道具・装備」から。綱と滑車で物をつかむ装置→相手に組みつく→「タックルする」、問題に組みつく→「取り組む」。', 'cde8e5705f086278'),
