  'tailor': clear('後期ラテン語 tāliāre「切る」から、古フランス語 tailleor「布を切る人」を経た語。布を切って服を作る人→「仕立屋・仕立てる」、目的に合わせて作る→「合わせる」。retail（小売り）と同じ語源。', '0f649db8014718eb'),
  'talent': clear('ギリシャ語 talanton「てんびん・重さとお金の単位」から、ラテン語を経た語。聖書の、主人から預かったお金を生かす話から→神から預けられた力→「才能・素質」。', '134d01253a265636'),
