  'tantamount': clear('アングロ・フランス語 tant amunter「同じだけの量になる」（tant「それほど」＋ amunter「達する」）から。同じ量になる→「同等の・等しい」。amount（量）と同じ語源。', '4477a25059d5928c'),
  'tap': clear('古フランス語 taper「軽くたたく」から。「軽くたたく」。「蛇口」「利用する」の tap は古英語 tæppa「栓」から来た別の語で、栓を開けて中身を取り出す→「利用する」。', '60a8a07f3f2bcd53'),
