  'target': clear('古フランス語 targe「盾」に小さいことを表す -et がついた語。弓の練習でねらった小さな丸い盾→「標的・目標・対象にする」。', '96c180c2f2279bb8'),
  'tarnish': clear('古フランス語 ternir「くすませる」（terne「くすんだ」から）から。金属の輝きをくすませる→「変色させる・くすむ」、評判をくすませる→「汚す」。', 'ea03362cfa98f41b'),
  'tart': clear('古英語 teart「鋭い・ひりひりする」から。「酸味のある」、ことばが鋭い→「辛辣な」。お菓子の「タルト」は古フランス語 tarte から来た別の語。', '6f82df12d40e3ea3'),
  'task': clear('中世ラテン語 tasca「課された税・務め」から、古北フランス語 tasque を経た語。割り当てられた務め→「仕事・課題・任務」。tax（税）と同じ語源。', '46e9cc54354e03f5'),
