  'tendentious': clear('ドイツ語 Tendenz「傾向」（ラテン語 tendere「向かう」にさかのぼる）をもとに作られた語。ある方向に傾いた→「偏向した・我田引水の」。tend（〜しがちだ）と同じ語源。', '72fe1dfcb7153dca'),
  'tender': clear('ラテン語 tener「柔らかい・か弱い」から、古フランス語 tendre を経た語。「柔らかい」、心が柔らかい→「優しい」、刺激を感じやすい→「敏感な」。', '8cd49ad9b158ee58'),
  'tenet': clear('ラテン語 tenet「（彼は）固く持っている」（tenēre「持つ」から）から。人々が固く守る考え→「主義・教義・信条」。', '5ce0ee2bb9797894'),
