  'terse': clear('ラテン語 tersus「ふいてきれいにした・磨かれた」（tergēre「ふく」から）から。むだをふき取った→「簡潔な・そっけない」。', '8b1bd7b38ae4f356'),
  'test': clear('ラテン語 testum「土の器」から、古フランス語を経た語。金属の質を調べるのに使った土のつぼ→質を調べる→「試験・検査・試す」。', '24e09270d2cc3a02'),
