  'thatch': clear('古英語 þæc「屋根・覆い」から。屋根をふく材料→「（屋根の）わら・かやぶき」。', 'd51c37a98015bdf0'),
  'them': clear('古ノルド語 þeim「彼らに」から。北欧から移り住んだ人々のことばが英語に入って→「彼らを・彼らに」。they（彼らは）と同じく北欧系の語。', '84b98ed9f965c130'),
  'theme': clear('ギリシャ語 thema「置かれたもの・議論の題」（tithenai「置く」から）から、ラテン語を経た語。話の中心に置かれたもの→「テーマ・主題」。', '99e312a9bb75108e'),
