  'thrill': clear('古英語 þyrlian「穴をあける・貫く」から。体を突き抜けるような感覚→「わくわくさせる・スリル」。', '4224785fd3451261'),
  'thrive': clear('古ノルド語 þrīfask「つかむ・栄える」から。うまくつかんで育つ→「繁栄する・よく育つ」。', '8ba6ccc15e9eb1f7'),
