  'tight': clear('中英語 tight「すき間のない」から（古ノルド語 þéttr「すき間のない」から来たとされる）。すき間のない→「きつい・ぴんと張った」。', 'e2a68474ef525ff7'),
  'tile': clear('ラテン語 tēgula「屋根がわら」（tegere「覆う」から）から、古英語を経た語。屋根を覆う板→「瓦・タイル・タイルを張る」。', '75ee21dfa38f7416'),
