  'tin': clear('古英語 tin「すず」から。「すず」、すずをめっきした鉄板→「ブリキ」、ブリキで作った入れ物→「缶」。', '353a8926f5852e0d'),
  'tiny': clear('中英語 tine「ごく少し」に -y がついた語。それより前の由来ははっきりしない。「ごく小さい」。', '50803cdc98e07550'),
  'tirade': clear('イタリア語 tirata「一気に引くこと・一続き」（tirare「引く」から）から、フランス語を経た語。一気にまくし立てる話→「長広舌・非難の連発」。', '347ff594ced96ee3'),
  'tissue': clear('古フランス語 tissu「織られた（布）」（ラテン語 texere「織る」にさかのぼる）から。薄く織った布→薄い紙→「ティッシュ」、細胞が織物のように集まったもの→「（生体）組織」。text（文章）と同じ語源。', '2803985a6244244f'),
