  'vehicle': clear('ラテン語 vehiculum「運ぶもの・車」（vehere「運ぶ」から）から。人や物を運ぶもの→「乗り物・車両」。', '83da90fb98d91897'),
  'veil': clear('ラテン語 vēlum「帆・覆いの布」から、古フランス語 veile を経た語。顔を覆う布→「ベール・覆い・覆い隠す」。', '860a382a6d6c1829'),
  'vein': clear('ラテン語 vēna「血管・水脈」から、古フランス語 veine を経た語。「静脈」、血管のように走る筋→「葉脈・鉱脈」。', 'a2cc96d81d408d34'),
