  'venal': clear('ラテン語 vēnālis「売り物の」（vēnum「売ること」から）から。お金で売り買いできる→「買収できる・金で動く」。', '110c3005e6d58c37'),
  'venality': clear('ラテン語 vēnālis「売り物の」から。お金で心を売ること→「買収のきくこと・汚職体質」。venal（金で動く）と同じ語源。', '8f66b835b4165002'),
  'vendor': clear('ラテン語 vendere「売る」（vēnum「売ること」＋ dare「与える」）から、アングロ・フランス語を経た語。売る人→「売り手・行商人」。', '231f9705de31cfad'),
