  'venom': clear('ラテン語 venēnum「毒・薬」から、古フランス語 venim を経た語。「毒液」、ことばにこめた毒→「悪意」。', 'e88be7284462fcd2'),
  'veracity': clear('ラテン語 vērāx「真実を語る」（vērus「真実の」から）から。「真実性・誠実さ」。very（とても）と同じ語源。', '4b3c9301a1f1a2fe'),
  'verdant': clear('古フランス語 verdoyant「緑になっている」（vert「緑」から）から。「青々とした・緑におおわれた」。', '6810b30ac6b8bf72'),
  'verge': clear('ラテン語 virga「小枝・棒」から、古フランス語を経た語。役人が持つ権威の棒→その棒の力が及ぶ範囲の境→「縁」、境目にさしかかる→「間際」。', 'f1322e98ba462851'),
  'very': clear('古フランス語 verai「本当の」（ラテン語 vērus「真実の」から）から。本当に→「とても・非常に」。', 'd0a01d8e81b61143'),
  'vessel': clear('後期ラテン語 vāscellum「小さな器」（vās「器」から）から、古フランス語を経た語。「容器」、人や物を運ぶ器→「船」、血を運ぶ管→「血管」。vase（花瓶）と同じ語源。', 'bfcd9201068c8b72'),
