  'vice': clear('ラテン語 vitium「欠点・悪いくせ」から、古フランス語を経た語。「悪徳・悪習・欠点」。「副〜」を表す vice（vice-president など）は vicis「代わり」から来た別の語。', '7c65beefe22e6bd5'),
