  'vicissitude': clear('ラテン語 vicissitūdō「移り変わり」（vicissim「代わる代わる」から）から。代わる代わる変わること→「変転・浮き沈み」。', '66a02e55c2f1c653'),
  'victim': clear('ラテン語 victima「いけにえの動物」から。神にささげられるいけにえ→犠牲になる人→「被害者・犠牲者」。', 'eb5728c3537109a9'),
  'vigor': clear('ラテン語 vigor「活力」（vigēre「生き生きしている」から）から。「活力・精力」。', 'f715bcd63a8aab14'),
