  'vinegar': clear('古フランス語 vin aigre「酸っぱいワイン」（vin「ワイン」＋ aigre「酸っぱい」）から。ワインが発酵して酸っぱくなったもの→「酢」。', '1c29febd0727070c'),
  'vintage': clear('古フランス語 vendange「ぶどうの収穫」（ラテン語 vīnum「ワイン」にさかのぼる）から。ある年に収穫したぶどうで造ったワイン→造られた年→「年式・年代物の・由緒ある」。', '1c0f5169d3668557'),
  'violate': clear('ラテン語 violāre「乱暴に扱う」（vīs「力」から）から。力ずくで破る→「違反する・侵害する」。violent（乱暴な）と同じ語源。', '3fd9238bec8c7308'),
  'virulence': clear('ラテン語 vīrus「毒」から（virulentus「毒に満ちた」）。毒の強さ→「毒性」、ことばにこもった毒の強さ→「（敵意の）激しさ」。', '953803452e2a7b7c'),
  'virulent': clear('ラテン語 virulentus「毒に満ちた」（vīrus「毒」から）から。「猛毒の」、ことばに毒がある→「悪意に満ちた」。virus（ウイルス）と同じ語源。', '4cec00f3a1033dac'),
