  'vitriolic': clear('中世ラテン語 vitriolum「硫酸塩」（vitrum「ガラス」から、ガラスのような結晶による）から。硫酸のように焼けつく→「辛辣な・痛烈な」。', '6a49ca1d6aad59f1'),
  'vituperative': clear('ラテン語 vituperāre「けなす」（vitium「欠点」＋ parāre「用意する」）から。欠点をあげつらう→「口汚くののしる・毒舌の」。', '705a050e6cc68cfc'),
  'vivacious': clear('ラテン語 vīvāx「生き生きした」（vīvere「生きる」から）から。「快活な・元気いっぱいの」。vivid（鮮やかな）と同じ語源。', 'eb653c2309f0edcc'),
