  'war': clear('古北フランス語 werre「争い」（ゲルマン系の語）から、後期古英語 werre を経た語。「戦争」。フランス語の guerre（戦争）と同じ語。', '65033eac6aad19b0'),
  'ward': clear('古英語 weard「見張り・守り」から。「保護する」、守られる区域→「行政区」、患者を守り世話する部屋→「病棟」。guard（守る）と同じ語源。', '3194f12d1ca3e2b3'),
